mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.RG_DT DESC) AS LISTNUM, A.FRM_UNQ_KY_VAL, A.PRCDOC_UNQ_KY_VAL, A.PRCDOC_CFY, CASE WHEN A.PRCDOC_CFY = 'P' THEN '정주기' WHEN A.PRCDOC_CFY = 'M' THEN '점검지' ELSE '' END AS PRCDOC_CFY_NM, B.PRCDOC_NO, B.PRCDOC_NM, B.DOC_TYP, A.PRCDOC_RVSN_NO, B.ATCT_NM, A.ATCT_CFY, (SELECT COUNT(1) FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM = 'GE_MP_FRM_M' AND UNQ_NO = A.FRM_UNQ_KY_VAL) AS ATFL_CNT, A.REGPR_ID, A.REGPR_NM, A.RG_DT, TO_CHAR(A.RG_DT, 'YYYY-MM-DD') AS FM_RG_DT, (SELECT ATFL_PHCL_NM||'.'||ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM = 'GE_MP_FRM_M' AND UNQ_NO = A.FRM_UNQ_KY_VAL AND ATFL_ID = '1') AS ATFL_PHCL_NM FROM GE_MP_FRM_M A JOIN GE_MP_PRCDOC_M B ON A.PRCDOC_UNQ_KY_VAL = B.PRCDOC_UNQ_KY_VAL AND A.PRCDOC_RVSN_NO = B.PRCDOC_RVSN_NO
AND B.PRCDOC_NO LIKE '%'||#{PRCDOC_NO}||'%'
AND B.PRCDOC_NM LIKE '%'||#{PRCDOC_NM}||'%'
WHERE 1 = 1 AND B.DLT_YN = 'N'
AND B.PRCDOC_CFY = #{PRCDOC_CFY}
ORDER BY B.PRCDOC_NM,B.ATCT_NM ) WHERE LISTNUM BETWEEN #{DISPSTART} AND #{DISPEND}

mapper.update:
UPDATE GE_MP_FRM_M SET PRCDOC_RVSN_NO = #{PRCDOC_RVSN_NO},
ATCT_NM = #{ATCT_NM}, ATCT_CFY = #{ATCT_CFY},
REGPR_ID = #{REGPR_ID}, REGPR_NM = #{REGPR_NM}, RG_DT = SYSDATE WHERE FRM_UNQ_KY_VAL = #{FRM_UNQ_KY_VAL}

mapper.select:
SELECT A.FRM_UNQ_KY_VAL, A.PRCDOC_UNQ_KY_VAL, A.PRCDOC_CFY, B.PPCD, B.PRCDOC_NO, B.PRCDOC_NM, B.DOC_TYP, B.RRD_CFY, A.PRCDOC_RVSN_NO, A.ATCT_NM, A.ATCT_CFY, A.REGPR_ID, A.REGPR_NM, A.RG_DT, TO_CHAR(A.RG_DT, 'YYYY-MM-DD') AS FM_RG_DT, (SELECT ATFL_GRUP_NM||'/'||ATFL_PHCL_NM||'.'||ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = A.FRM_UNQ_KY_VAL AND ATFL_ID = '1') ATFL_PHCL_NM1, (SELECT ATFL_TITL_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = A.FRM_UNQ_KY_VAL AND ATFL_ID = '1') ATFL_TITL_NM1, (SELECT ATFL_ORSRC_NM||'.'||ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = A.FRM_UNQ_KY_VAL AND ATFL_ID = '1') ATFL_ORSRC_NM1, (SELECT ATFL_GRUP_NM||'/'||ATFL_PHCL_NM||'.'||ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = A.FRM_UNQ_KY_VAL AND ATFL_ID = '2') ATFL_PHCL_NM2, (SELECT ATFL_TITL_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = A.FRM_UNQ_KY_VAL AND ATFL_ID = '2') ATFL_TITL_NM2, (SELECT ATFL_GRUP_NM||'/'||ATFL_PHCL_NM||'.'||ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = A.FRM_UNQ_KY_VAL AND ATFL_ID = '3') ATFL_PHCL_NM3, (SELECT ATFL_TITL_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = A.FRM_UNQ_KY_VAL AND ATFL_ID = '3') ATFL_TITL_NM3, (SELECT ATFL_GRUP_NM||'/'||ATFL_PHCL_NM||'.'||ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = A.FRM_UNQ_KY_VAL AND ATFL_ID = '4') ATFL_PHCL_NM4, (SELECT ATFL_TITL_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = A.FRM_UNQ_KY_VAL AND ATFL_ID = '4') ATFL_TITL_NM4, (SELECT ATFL_GRUP_NM||'/'||ATFL_PHCL_NM||'.'||ATFL_FEXT_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = A.FRM_UNQ_KY_VAL AND ATFL_ID = '5') ATFL_PHCL_NM5, (SELECT ATFL_TITL_NM FROM GE_MP_FILE_S WHERE ATFL_GRUP_NM ='GE_MP_FRM_M' AND UNQ_NO = A.FRM_UNQ_KY_VAL AND ATFL_ID = '5') ATFL_TITL_NM5, (SELECT FRM_OVER_JSON FROM GE_MP_FRM1_M WHERE FRM_UNQ_KY_VAL = A.FRM_UNQ_KY_VAL) FRM_OVER_JSON, (SELECT FRM_CONS_JSON FROM GE_MP_FRM1_M WHERE FRM_UNQ_KY_VAL = A.FRM_UNQ_KY_VAL) FRM_CONS_JSON FROM GE_MP_FRM_M A JOIN GE_MP_PRCDOC_M B ON A.PRCDOC_UNQ_KY_VAL = B.PRCDOC_UNQ_KY_VAL WHERE A.PRCDOC_UNQ_KY_VAL = #{PRCDOC_UNQ_KY_VAL}
AND A.FRM_UNQ_KY_VAL = #{FRM_UNQ_KY_VAL}
ORDER BY PRCDOC_RVSN_NO DESC
